```csharp
using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;
using System.Collections.Generic;

public class RestServiceWrapper<T>
{
    private readonly string _baseAddress;
    private readonly string _authToken;

    public RestServiceWrapper(string baseAddress, string authToken)
    {
        _baseAddress = baseAddress;
        _authToken = authToken;
    }

    public async Task<T> GetAsync(string path)
    {
        using (var client = new HttpClient())
        {
            client.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", _authToken);
            var response = await client.GetAsync($"{_baseAddress}{path}");
            if (response.IsSuccessStatusCode)
            {
                var content = await response.Content.ReadAsStringAsync();
                return JsonConvert.DeserializeObject<T>(content);
            }
            else
            {
                throw new Exception($"Error occurred while fetching data from {_baseAddress}{path}. Status code: {response.StatusCode}");
            }
        }
    }

    public async Task<T> PostAsync(string path, object data)
    {
        using (var client = new HttpClient())
        {
            client.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", _authToken);
            var content = new StringContent(JsonConvert.SerializeObject(data), Encoding.UTF8, "application/json");
            var response = await client.PostAsync($"{_baseAddress}{path}", content);
            if (response.IsSuccessStatusCode)
            {
                var content1 = await response.Content.ReadAsStringAsync();
                return JsonConvert.DeserializeObject<T>(content1);
            }
            else
            {
                throw new Exception($"Error occurred while posting data to {_baseAddress}{path}. Status code: {response.StatusCode}");
