Here's a simple Go program that generates an AVRO schema from a given Go struct:

```go
package main

import (
	"fmt"
	"os"

	"github.com/apache/avro/avro"
)

type MyStruct struct {
	Field1 string `avro:"field1"`
	Field2 int    `avro:"field2"`
}

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: ./generate_schema <go_source_file> <struct_name>")
		return
	}

	goSourceFile := os.Args[1]
	structName := os.Args[2]

	// Parse the Go struct
	structType, err := parseGoStruct(goSourceFile, structName)
	if err != nil {
		fmt.Println(err)
		return
	}

	// Generate the AVRO schema
	schema, err := structType.ToAVROSchema()
	if err != nil {
		fmt.Println(err)
		return
	}

	// Write the AVRO schema to a file
	err = os.WriteFile("struct.avsc", schema, 0644)
	if err != nil {
		fmt.Println(err)
		return
	}

	fmt.Println("AVRO schema generated successfully!")
}

