To retrieve the username from the JWT token in ASP.NET C# WebAPI, you can follow these steps:

1. Install the `Microsoft.IdentityModel.Tokens` package if you haven't already. You can do this by running the following command in the Package Manager Console:
```
Install-Package Microsoft.IdentityModel.Tokens
```
2. In your WebAPI project, create a new class that will handle the authentication and token validation. For example:
```csharp
using System;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using Microsoft.IdentityModel.Tokens;

public class JwtAuthentication
{
    private readonly string _secretKey;

    public JwtAuthentication(string secretKey)
    {
        _secretKey = secretKey;
    }

    public ClaimsPrincipal GetPrincipalFromToken(string token)
    {
        var tokenHandler = new JwtSecurityTokenHandler();
        var key = Encoding.ASCII.Parse(_secretKey);
        var tokenValidationParameters = new TokenValidationParameters
        {
            IssuerSigningKey = key,
            ValidateIssuer = false,
            ValidateAudience = false,
            ValidateLifetime = true,
            RequireExpirationTime = true,
            ClockSkew = TimeSpan.Zero
        };

        var securityToken = tokenHandler.ReadJwtToken(token, tokenValidationParameters);
        return new ClaimsPrincipal(securityToken.Claims);
    }
}
```
3. In your WebAPI controller, inject the `JwtAuthentication` class and use it to authenticate the user and retrieve the username. For example:
```csharp
