% Define the population size and initial genotypes
population_size = 100;
genotypes = randi([0 1], population_size, 2); % 2 loci, each with 0 or 1 allele

% Define the fitness function
fitness = @(g) sum(g); % Fitness is proportional to the number of favorable alleles

% Simulate natural selection for 100 generations
for i = 1:100
    % Evaluate fitness of each individual
    fit = fitness(genotypes);

    % Select parents based on fitness
    parents = genotypes(sort(fit, 'descend'), :);

    % Create offspring by crossing over between parents
    crossover_point = randi([1 size(parents, 1)-1]);
    offspring = zeros(population_size, 2);
    for j = 1:population_size
        offspring(j, 1) = parents(randi([1 size(parents, 1)]), 1);
        offspring(j, 2) = parents(randi([1 size(parents, 1)]), 2);
    end

    % Mutate offspring with a small probability
    mutation_rate = 0.01;
    for j = 1:population_size
        if rand() < mutation_rate
            offspring(j, 1) = ~offspring(j, 1);
            offspring(j, 2) = ~offspring(j, 2);
        end
    end

    % Replace the parent population with the offspring population
    genotypes = offspring;
end

% Print the final genotype frequencies
fprintf('Final genotype frequencies:\n');
disp(sum(genotypes, 2)/population_size);
```

