```R
# Function to check if all non-NA elements in a character vector can be converted to numeric
is_all_numeric <- function(x) {
  is_numeric <- function(x) {
    tryCatch({
      as.numeric(x)
      TRUE
    }, error = function(e) FALSE)
  }

  all(!is.na(x)) & all(sapply(x, is_numeric))
}

# Example usage
x <- c("1", "2", "3", NA, "4")
print(is_all_numeric(x)) # Output: [1] FALSE

y <- c("1", "2", "3", "4")
print(is_all_numeric(y)) # Output: [1] TRUE
```

Here's a decorator for Nest.js middleware that checks the `NODE_ENV` variable and returns `false` if it's not equal to `true`. If `NODE_ENV` is equal to `true`, it calls the `next()` function to continue executing the middleware chain.

```typescript
import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';

@Injectable()
export class EnvironmentMiddleware implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const request = context.switchToHttp().getRequest();
    const nodeEnv = process.env.NODE_ENV;

    if (nodeEnv === 'true') {
      return true;
    }

    return false;
  }
}
```

To use this middleware, you can add it to your Nest.js module's `middleware` array in the `app.module.ts` file:

```typescript
import { Module } from '@nestjs/common';
import { EnvironmentMiddleware } from './environment.middleware';

@Module({
  imports: [],
  controllers: [],
  providers: [EnvironmentMiddleware],
  middleware: [EnvironmentMiddleware],
})
export class AppModule {}
```

This will ensure that the `EnvironmentMiddleware` is executed before any other middleware in your application. If the `NODE_ENV` variable is set to `true`, the middleware will allow the request to proceed to the next middleware in the chain. If the `NODE_ENV` variable is set to anything else, the middleware will return `false` and prevent the request from continuing.

