To create a simple toast notification using React context, follow these steps:

1. Create a ToastContext file:

```javascript
import React from 'react';

const ToastContext = React.createContext();

function ToastProvider({ children }) {
  const [toast, setToast] = React.useState(null);

  function showToast(message) {
    setToast(message);
  }

  return (
    <ToastContext.Provider value={{ showToast }}>
      {children}
    </ToastContext.Provider>
  );
}

export { ToastContext, ToastProvider };
```

2. Import the ToastContext and ToastProvider in your app:

```javascript
import React from 'react';
import { ToastContext, ToastProvider } from './ToastContext';

function App() {
  return (
    <ToastProvider>
      <div>
        {/* Your app content goes here */}
        <button onClick={() => showToast('Hello, world!')}>Show Toast</button>
      </div>
    </ToastProvider>
  );
}

export default App;
```

3. Use the ToastContext in your components:

```javascript
import React from 'react';
import { useContext } from 'react';
import { ToastContext } from './ToastContext';

function MyComponent() {
  const { showToast } = useContext(ToastContext);

  return (
    <div>
      <button onClick={() => showToast('Hello, world!')}>Show Toast</button>
    </div>
  );
}

export default MyComponent;
```

Now you have a simple toast notification system using React context. You can use the `showToast` function to display toast messages in your components.

