```typescript
// Data interface
interface Data {
  name: string;
  value: number;
}

// Bar chart options interface
interface BarChartOptions {
  width: number;
  height: number;
  margin: { top: number; right: number; bottom: number; left: number };
  colors: string[];
  labels: string[];
}

// Bar chart function
function createBarChart(data: Data[], options: BarChartOptions): HTMLCanvasElement {
  // Create canvas element
  const canvas = document.createElement('canvas');
  canvas.width = options.width;
  canvas.height = options.height;

  // Get context for drawing
  const ctx = canvas.getContext('2d');

  // Set margins
  const margin = options.margin;
  const width = canvas.width - margin.left - margin.right;
  const height = canvas.height - margin.top - margin.bottom;

  // Create bars
  data.forEach((datum, index) => {
    const barWidth = width * datum.value / 100;
    const barHeight = height;
    const barX = margin.left + index * (barWidth + margin.right);
    const barY = height - datum.value;

    ctx.fillStyle = options.colors[index];
    ctx.fillRect(barX, barY, barWidth, barHeight);
  });

  // Add labels
  options.labels.forEach((label, index) => {
    const labelX = margin.left + index * (barWidth + margin.right) + barWidth / 2;
    const labelY = height - margin.bottom - 10;

    ctx.font = '14px Arial';
    ctx.fillStyle = 'black';
    ctx.fillText(label, labelX, labelY);
  });

  return canvas;
}

